import{_ as t,D as n,o as c,c as r,m as l,a as i,G as a,S as y}from"./chunks/framework.DuIEtbrD.js";const B=JSON.parse('{"title":"Typescript全局类型声明","description":"一文搞懂Typescript全局类型声明中使用技巧，你将全面掌握类型扩展、declare、namespace、module、三斜线指令的使用秘方","frontmatter":{"title":"Typescript全局类型声明","description":"一文搞懂Typescript全局类型声明中使用技巧，你将全面掌握类型扩展、declare、namespace、module、三斜线指令的使用秘方","keywords":"declare,类型声明,三斜线指令,module,namespace,类型扩展,扩展第三方包,全局声明","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/icon-ts.png"},"headers":[],"relativePath":"frontend/ts/declare.md","filePath":"frontend/ts/declare.md","lastUpdated":1776945570000}'),F={name:"frontend/ts/declare.md"};function D(d,s,u,b,m,C){const e=n("Obsolete"),p=n("Reward"),o=n("Gitalk");return c(),r("div",null,[s[0]||(s[0]=l("h1",{id:"typescript全局类型声明",tabindex:"-1"},[i("Typescript全局类型声明 "),l("a",{class:"header-anchor",href:"#typescript全局类型声明","aria-label":'Permalink to "Typescript全局类型声明"'},"​")],-1)),a(e,{date:"2020-11-19"}),s[1]||(s[1]=y(`<p>现阶段的前端项目越来越少不了第三方库的使用，而第三方库不一定都是用ts编写的、也不一定都遵守了统一规范，那么这种情况下在ts项目中就会出现找不到变量相关类型声明的情况，这时候就需要在项目中进行全局类型声明了</p><p>又或者在大型项目中需要在全局定义一些全局变量、给全局对象补充自定义属性方法等等，这些都需要用到全局类型声明</p><p>本文就来看看全局类型声明及相关一些技巧吧</p><div class="warning custom-block"><p class="custom-block-title">小贴士</p><p>文章中涉及到的代码示例你都可以从 <a href="https://github.com/ihengshuai/blog-case/tree/gh-pages/ts/declare" target="_blank" rel="noreferrer">这里查看</a> ，若对你有用还望点赞支持；你可以在 <a href="https://www.typescriptlang.org/play/" target="_blank" rel="noreferrer">TS Playground</a> 尝试开始Typescript的学习</p></div><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>类型声明需要在<code>.d.ts</code>或<code>.ts</code>结尾的文件中定义，且需要在<code>tsconfig.json</code>中包含类型定义文件</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">include</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> [</span><span style="color:#676E95;font-style:italic;">/* 类型定义文件 */</span><span style="color:#89DDFF;">]</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>ts中的模块有<code>全局模块(ambient module)</code>和<code>文件模块</code>之分，什么意思呢❓</p><p>假设有个<code>a.ts</code>：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">type</span><span style="color:#FFCB6B;"> ICard</span><span style="color:#89DDFF;"> =</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#C792EA;">interface</span><span style="color:#FFCB6B;"> IUser</span><span style="color:#89DDFF;"> {};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>此时<code>a.ts</code>就是全局模块，里面声明的类型，<u>在其他文件不引入也可以正常使用</u></p><p>再看看<code>b.d.ts</code>文件：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">type</span><span style="color:#FFCB6B;"> ICard</span><span style="color:#89DDFF;"> =</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">export</span><span style="color:#C792EA;"> interface</span><span style="color:#FFCB6B;"> IUser</span><span style="color:#89DDFF;"> {};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>此时<code>b.d.ts</code>就是个文件模块，里面的类型变量就不再是全局的了，必须要使用<code>import</code>引入才可以使用。那么<code>IUser</code>可以使用，<code>ICard</code>没有导出是没法使用的</p><p>如果一个文件中包含了<code>import/export</code>引入第三方模块了，里面的变量将不再是全局变量</p><p>那全部使用第一种方式很有可能造成变量污染，使类型声明不可控，通常我们都是遵循：<u>项目级别和第三方模块类型可声明全局，而普通的变量类型以文件模块声明，使用时以导入导出的形式加载</u></p><h2 id="扩展window对象" tabindex="-1">扩展window对象 <a class="header-anchor" href="#扩展window对象" aria-label="Permalink to &quot;扩展window对象&quot;">​</a></h2><p>工作中被同事问到扩展window对象属性的问题最多，其实很简单</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">interface</span><span style="color:#FFCB6B;"> Window</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">  __DEV__</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> boolean</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#F07178;">  __DATE__</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>或者经常看到有人这样用：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">declare</span><span style="color:#BABED8;"> global </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#C792EA;">  interface</span><span style="color:#FFCB6B;"> window</span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">    __DEV__</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> boolean</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#F07178;">    __DATE__</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">export</span><span style="color:#89DDFF;"> {};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>第二种其实多此一举，这里global被看做其他模块了，所以要使用<code>export {}</code>，不然会报错</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-02-13_07.51.05.png" alt=""></p><h2 id="declare" tabindex="-1">declare <a class="header-anchor" href="#declare" aria-label="Permalink to &quot;declare&quot;">​</a></h2><p>上面我们看到了<code>declare</code>关键字，这个关键字用来表示已经真实存在的变量、类型、函数、模块等等</p><p>举几个例子：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">declare</span><span style="color:#C792EA;"> const</span><span style="color:#BABED8;"> __DEV__</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> boolean</span><span style="color:#89DDFF;">;</span><span style="color:#676E95;font-style:italic;"> // 全局变量</span></span>
<span class="line"><span style="color:#C792EA;">declare</span><span style="color:#C792EA;"> function</span><span style="color:#82AAFF;"> logger</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">msg</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">):</span><span style="color:#FFCB6B;"> void</span><span style="color:#89DDFF;">;</span><span style="color:#676E95;font-style:italic;">  // 全局函数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="命名空间namespace" tabindex="-1">命名空间namespace <a class="header-anchor" href="#命名空间namespace" aria-label="Permalink to &quot;命名空间namespace&quot;">​</a></h2><p>namespace 类似于 JavaScript 中的作用域。通过 namespace 开发者可以将相关的类型、函数、变量等元素封装在一个逻辑容器内，从而<u>避免全局命名空间污染，并提高代码的可维护性和可读性</u></p><p>使用namespace很简单，用固定格式定义模块，然后内部使用<code>export</code>暴露变量就可以，基本上和模块导出类似，而没有导出的变量是没法使用的</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">// 定义Color命名空间</span></span>
<span class="line"><span style="color:#C792EA;">declare</span><span style="color:#C792EA;"> namespace</span><span style="color:#FFCB6B;"> Color</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  export</span><span style="color:#C792EA;"> const</span><span style="color:#BABED8;"> red</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  export</span><span style="color:#C792EA;"> const</span><span style="color:#BABED8;"> green</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  export</span><span style="color:#C792EA;"> const</span><span style="color:#BABED8;"> blue</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// 使用</span></span>
<span class="line"><span style="color:#C792EA;">let</span><span style="color:#BABED8;"> color </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> Color</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">blue</span><span style="color:#89DDFF;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>注意上面的<code>Color.blue</code>的Color不是<code>namespace Color</code>的那个Color，一定要知道<u>declare只是声明存在，并不代表真实的对象</u></p><p>或者你也可以不用<code>declare</code>关键字，那么定义的就是真实值</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">// 这里就是真实对象，必须初始化值</span></span>
<span class="line"><span style="color:#C792EA;">namespace</span><span style="color:#FFCB6B;"> Colors</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  export</span><span style="color:#C792EA;"> const</span><span style="color:#BABED8;"> red</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">RED</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  export</span><span style="color:#C792EA;"> const</span><span style="color:#BABED8;"> green</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">green</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  export</span><span style="color:#C792EA;"> const</span><span style="color:#BABED8;"> blue</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">blue</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> color </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> Colors</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">red</span><span style="color:#89DDFF;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="模块module" tabindex="-1">模块module <a class="header-anchor" href="#模块module" aria-label="Permalink to &quot;模块module&quot;">​</a></h2><p><code>declare module</code> 是一种用于声明模块接口的方式，主要用于告诉TypeScript编译器某个模块的存在及其包含的内容。这种声明方式特别适用于处理外部模块或为现有的JavaScript代码添加TypeScript类型信息</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">declare</span><span style="color:#C792EA;"> module</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">module-name</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  // 模块的成员定义</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>比如现在使用比较老版本的jQuery，没有任何类型信息，这时候就可以使用<code>declare module</code>来声明jQuery中的成员变量</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">declare</span><span style="color:#C792EA;"> module</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">jquery</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#C792EA;">  const</span><span style="color:#BABED8;"> $</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> (</span><span style="color:#BABED8;font-style:italic;">selector</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">)</span><span style="color:#C792EA;"> =&gt;</span><span style="color:#FFCB6B;"> any</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  // ...</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// 使用jquery</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> jquery </span><span style="color:#89DDFF;font-style:italic;">from</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">jquery</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#BABED8;">jquery</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">$</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&#39;&#39;</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span><span style="color:#676E95;font-style:italic;"> // 这里就有类型提示了</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>module和namespace的区别❓</strong></p><ul><li>module主要用来在全局声明第三方模块中的成员变量类型信息，来弥补第三方库类型缺陷</li><li>namespace是ts提供的代码分割代码作用域的一种手段，既可以用来声明作用域类型，也可以生成作用域真实的变量成员</li></ul><p>在ts中推荐使用module来声明模块类型‼️</p><p>当然也可以扩展第三方模块的类型：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">vue</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#C792EA;">declare</span><span style="color:#C792EA;"> module</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">vue</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">  export</span><span style="color:#C792EA;"> interface</span><span style="color:#FFCB6B;"> AppConfig</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#C792EA;">    readonly</span><span style="color:#F07178;"> __APP_VERSION__</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#C792EA;">  const</span><span style="color:#BABED8;"> launch</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> ()</span><span style="color:#C792EA;"> =&gt;</span><span style="color:#FFCB6B;"> void</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// 使用</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#89DDFF;"> {</span><span style="color:#BABED8;"> createApp</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;"> launch</span><span style="color:#89DDFF;"> }</span><span style="color:#89DDFF;font-style:italic;"> from</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">vue</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> app </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> createApp</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">{}</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#BABED8;">app</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">config</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">__APP_VERSION__</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#82AAFF;">launch</span><span style="color:#BABED8;">()</span><span style="color:#89DDFF;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">小贴士</p><p>扩展类型一定要遵循可扩展规范，如类型一定要使用<code>interface</code>定义才可以扩展，而使用<code>type</code>是没办法扩展的</p></div><h2 id="三斜线指令" tabindex="-1">三斜线指令 <a class="header-anchor" href="#三斜线指令" aria-label="Permalink to &quot;三斜线指令&quot;">​</a></h2><p>三斜线指令（Triple-Slash Directives）是一种用于向编译器提供额外信息的特殊注释。这些指令可以帮助开发者更好地管理模块和类型定义，特别是在处理大型项目或混合型代码库时非常有用</p><p>最简单的形式是：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">/// </span><span style="color:#89DDFF;font-style:italic;">&lt;</span><span style="color:#F07178;font-style:italic;">reference</span><span style="color:#C792EA;font-style:italic;"> path</span><span style="color:#89DDFF;font-style:italic;">=</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#C3E88D;font-style:italic;">file.ts</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#89DDFF;font-style:italic;"> /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这行代码告诉TypeScript编译器在编译当前文件时，也包含指定的<code>file.ts</code>中的内容。这意味着如果<code>file.ts</code>中有一些共享的类型定义或接口，使用这个指令可以让所有引用它的文件都能访问到这些类型</p><p>但是在前面<code>前置知识</code>那里，我们讲了项目中定义的类型如果没有<code>export/import</code>都会被视为全局变量，在项目中的任何地方都可以访问到，那还是用三斜线的意义在哪里❓</p><p>需要注意的是如果使用到的类型没有被包含在<code>tsconfig</code>中的<code>include</code>中，就无法识别到。那你可能会说，可以使用：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#89DDFF;"> {</span><span style="color:#BABED8;"> someType</span><span style="color:#89DDFF;"> }</span><span style="color:#89DDFF;font-style:italic;"> from</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">some-module</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>来显示引入它来解决问题。但这种方式并没法使用模块中没有导出的变量</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">// 可使用，因为导出了</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">export</span><span style="color:#C792EA;"> interface</span><span style="color:#FFCB6B;"> IUser</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">  name</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// 没有导出，不可以使用</span></span>
<span class="line"><span style="color:#C792EA;">type</span><span style="color:#FFCB6B;"> person</span><span style="color:#89DDFF;"> =</span><span style="color:#FFCB6B;"> boolean</span><span style="color:#89DDFF;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>这时候三斜线指令就发挥作用了：</p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">/// </span><span style="color:#89DDFF;font-style:italic;">&lt;</span><span style="color:#F07178;font-style:italic;">reference</span><span style="color:#C792EA;font-style:italic;"> path</span><span style="color:#89DDFF;font-style:italic;">=</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#C3E88D;font-style:italic;">../some-module</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#89DDFF;font-style:italic;"> /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这样就可以使用<code>person</code>了，但是你会发现<code>IUser</code>又没法使用了，所以到这里你应该明白：</p><p><u>三斜线指令主要用来引入不想暴露出去的类型声明文件，尤其是那些第三方库文件，没有暴露出去的类型，可以使用此种方式访问到</u></p><p><strong>常见的几种三斜线指令</strong></p><div class="language-ts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">/// </span><span style="color:#89DDFF;font-style:italic;">&lt;</span><span style="color:#F07178;font-style:italic;">reference</span><span style="color:#C792EA;font-style:italic;"> path</span><span style="color:#89DDFF;font-style:italic;">=</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#C3E88D;font-style:italic;">文件路径</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#89DDFF;font-style:italic;"> /&gt;</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/// </span><span style="color:#89DDFF;font-style:italic;">&lt;</span><span style="color:#F07178;font-style:italic;">reference</span><span style="color:#C792EA;font-style:italic;"> types</span><span style="color:#89DDFF;font-style:italic;">=</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#C3E88D;font-style:italic;">模块</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#89DDFF;font-style:italic;"> /&gt;</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/// </span><span style="color:#89DDFF;font-style:italic;">&lt;</span><span style="color:#F07178;font-style:italic;">reference</span><span style="color:#C792EA;font-style:italic;"> lib</span><span style="color:#89DDFF;font-style:italic;">=</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#C3E88D;font-style:italic;">内置模块</span><span style="color:#89DDFF;font-style:italic;">&quot;</span><span style="color:#89DDFF;font-style:italic;"> /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li><code>path</code>：主要引入某个具体的文件</li><li><code>types</code>：主要引入某个库或者包的类型，如node、vue等等</li><li><code>lib</code>：主要引入ts标准内置库中的某个模块类型，如dom等等</li></ul><h2 id="发布有类型声明的库" tabindex="-1">发布有类型声明的库 <a class="header-anchor" href="#发布有类型声明的库" aria-label="Permalink to &quot;发布有类型声明的库&quot;">​</a></h2><p>现在你有一个使用ts开发的工具库已经通过测试后想发布到公网，提供自己日常工作使用，需要注意点是什么呢，或者如何在项目中正确识别到第三方库类型呢？</p><p>首先打包自己的工具包，一定要注意ts要开启类型声明配置：</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">compilerOptions</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#FFCB6B;">target</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">ESNext</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#FFCB6B;">module</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">ESNext</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#FFCB6B;">moduleResolution</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">node</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#FFCB6B;">outDir</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">dist</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">    // 开启类型声明</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#FFCB6B;">declaration</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> true,</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">    // 类型输出目录</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#FFCB6B;">declarationDir</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">dist/types</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">  },</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">include</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> [</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">./src/**/*</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">]</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>然后需要在<code>package.json</code>中定义类型路径：</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">types</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">./dist/types/main.d.ts</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这样在项目中引入工具库时，就会根据查找原则找到<code>types</code>，就可以正确显示类型了，当然需要将暴露给外部的类型通过<code>export</code>导出，如果没有可以使用<code>三斜线指令</code></p><p>除此之外，如果工具包产物中没有类型声明时，也可以专门定义一个<a href="https://github.com/DefinitelyTyped/DefinitelyTyped" target="_blank" rel="noreferrer">@types/工具包</a>的库，然后项目中会自动查找<code>@types</code>下的类型声明文件。官方提供了<a href="https://github.com/microsoft/DefinitelyTyped-tools/tree/main/packages/publisher" target="_blank" rel="noreferrer">types-publisher tool</a> 可以参考</p><h2 id="开发技巧" tabindex="-1">开发技巧 <a class="header-anchor" href="#开发技巧" aria-label="Permalink to &quot;开发技巧&quot;">​</a></h2><ul><li>项目中自定义的全局变量声明在一个文件中</li><li>对于第三方模块文件扩展放在一个文件</li><li>项目中的普通类型使用模块类型导入导出使用</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>到这里基本上已足以在工作中胜任Typescript了，那些深度类型体操相关不是很重要，通常也不会用到。后面就是装饰器的高级知识了，它不仅是一个语法，也是一种设计模式，搞明白它也比较重要</p>`,74)),a(p),a(o)])}const g=t(F,[["render",D]]);export{B as __pageData,g as default};
